///! PulseChain deposit contract replacement
///!
///! Replaces the Ethereum deposit contract with the PulseChain deposit contract
///! at the PrimordialPulse fork block.
use alloc::vec::Vec;
use alloy_primitives::{address, hex, Address, Bytes, B256, U256};

/// Ethereum mainnet deposit contract address
///
/// This contract is self-destructed and replaced with a nil contract at the PrimordialPulse fork.
pub const ETHEREUM_DEPOSIT_CONTRACT: Address = address!("00000000219ab540356cBB839Cbe05303d7705Fa");

/// PulseChain deposit contract address
///
/// This is the new deposit contract deployed at the PrimordialPulse fork.
pub const PULSECHAIN_DEPOSIT_CONTRACT: Address =
    address!("3693693693693693693693693693693693693693");

/// PulseChain deposit contract bytecode
///
/// This is the full bytecode of the PulseChain deposit contract that gets deployed
/// at the PrimordialPulse fork.
pub const DEPOSIT_CONTRACT_BYTECODE: &[u8] = &hex!("");

/// Nil contract bytecode
///
/// This is an empty contract with no receive() or fallback() function,
/// preventing users/contracts from sending PLS to the Ethereum deposit contract address.
pub const NIL_CONTRACT_BYTECODE: &[u8] =
    &hex!("6080604052600080fdfea2646970667358221220d10eb20cd2b73b968672d3bce97dff1eb0797edc10179828d6039dc6b4eda2fe64736f6c634300060b0033");

