/// Deposit contract data for easy access
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DepositContractData {
    /// The bytecode to deploy
    pub bytecode: Bytes,
    /// The storage slots to initialize
    pub storage: Vec<(U256, B256)>,
}

/// Get the PulseChain deposit contract data
pub fn get_deposit_contract_data() -> DepositContractData {
    DepositContractData {
        bytecode: Bytes::copy_from_slice(DEPOSIT_CONTRACT_BYTECODE),
        storage: DEPOSIT_CONTRACT_STORAGE
            .iter()
            .map(|(slot, value)| (U256::from(*slot), *value))
            .collect(),
    }
}

/// Get the nil contract bytecode for the Ethereum deposit contract
pub fn get_nil_contract_bytecode() -> Bytes {
    Bytes::copy_from_slice(NIL_CONTRACT_BYTECODE)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_deposit_contract_addresses() {
        assert_eq!(ETHEREUM_DEPOSIT_CONTRACT, address!("00000000219ab540356cBB839Cbe05303d7705Fa"));
        assert_eq!(
            PULSECHAIN_DEPOSIT_CONTRACT,
            address!("3693693693693693693693693693693693693693")
        );
    }

    #[test]
    fn test_deposit_contract_bytecode_not_empty() {
        assert!(DEPOSIT_CONTRACT_BYTECODE.len() > 0);
        assert!(NIL_CONTRACT_BYTECODE.len() > 0);

        // Verify bytecode starts with expected patterns
        assert_eq!(DEPOSIT_CONTRACT_BYTECODE[0], 0x60); // PUSH1
        assert_eq!(NIL_CONTRACT_BYTECODE[0], 0x60); // PUSH1
    }

    #[test]
    fn test_deposit_contract_storage() {
        // Should have 31 storage slots (0x22 through 0x40)
        assert_eq!(DEPOSIT_CONTRACT_STORAGE.len(), 31);

        // Verify first and last storage slots
        assert_eq!(DEPOSIT_CONTRACT_STORAGE[0].0, 0x22);
        assert_eq!(DEPOSIT_CONTRACT_STORAGE[30].0, 0x40);

        // Verify storage slots are sequential
        for i in 0..DEPOSIT_CONTRACT_STORAGE.len() {
            assert_eq!(DEPOSIT_CONTRACT_STORAGE[i].0, 0x22 + i as u64);
        }

        // Verify all values are non-zero
        for (_, value) in DEPOSIT_CONTRACT_STORAGE {
            assert_ne!(*value, B256::ZERO);
        }
    }

    #[test]
    fn test_get_deposit_contract_data() {
        let data = get_deposit_contract_data();

        assert_eq!(data.bytecode.len(), DEPOSIT_CONTRACT_BYTECODE.len());
        assert_eq!(data.storage.len(), 31);

        // Verify storage conversion
        assert_eq!(data.storage[0].0, U256::from(0x22));
        assert_eq!(data.storage[30].0, U256::from(0x40));
    }

    #[test]
    fn test_get_nil_contract_bytecode() {
        let bytecode = get_nil_contract_bytecode();
        assert_eq!(bytecode.len(), NIL_CONTRACT_BYTECODE.len());
        assert!(bytecode.len() > 0);
    }

    #[test]
    fn test_storage_values_match_go_pulse() {
        // Verify first storage slot matches go-pulse
        assert_eq!(
            DEPOSIT_CONTRACT_STORAGE[0].1,
            B256::new(hex!("f5a5fd42d16a20302798ef6ed309979b43003d2320d9f0e8ea9831a92759fb4b"))
        );

        // Verify last storage slot matches go-pulse
        assert_eq!(
            DEPOSIT_CONTRACT_STORAGE[30].1,
            B256::new(hex!("985e929f70af28d0bdd1a90a808f977f597c7c778c489e98d3bd8910d31ac0f7"))
        );
    }
}
